    // Boundary and failure handling: Null check
    if ((raw_t == NULL) || (bias_t == NULL) || (calibration == NULL) || (corrected_t == NULL)) {
        corrected_t->x = 0.0;
        corrected_t->y = 0.0;
        corrected_t->z = 0.0;
        return ADCS_E_NULL;
    }

    // Boundary and failure handling: Nonfinite check
    if ((!isfinite(raw_t->x)) || (!isfinite(raw_t->y)) || (!isfinite(raw_t->z)) ||
        (!isfinite(bias_t->x)) || (!isfinite(bias_t->y)) || (!isfinite(bias_t->z))) {
        corrected_t->x = 0.0;
        corrected_t->y = 0.0;
        corrected_t->z = 0.0;
        return ADCS_E_NOT_FINITE;
    }

    // Required processing: Subtract bias first
    double delta_x = raw_t->x - bias_t->x;
    double delta_y = raw_t->y - bias_t->y;
    double delta_z = raw_t->z - bias_t->z;

    // Required processing: Multiply by matrix rows
    // X axis / corrected.x uses C[0] row
    corrected_t->x = calibration->m[0][0] * delta_x + 
                     calibration->m[0][1] * delta_y + 
                     calibration->m[0][2] * delta_z;

    // Y axis / corrected.y uses C[1] row
    corrected_t->y = calibration->m[1][0] * delta_x + 
                     calibration->m[1][1] * delta_y + 
                     calibration->m[1][2] * delta_z;

    // Z axis / corrected.z uses C[2] row
    corrected_t->z = calibration->m[2][0] * delta_x + 
                     calibration->m[2][1] * delta_y + 
                     calibration->m[2][2] * delta_z;

    // Output contract: Success
    return ADCS_OK;
}

